describe('ZIP Code Auto-Formatting', () => {
    beforeEach(() => {
        cy.visit('/your-form-page-url'); // Replace with the actual URL of the form page
    });

    it('should auto-format ZIP code correctly as user types', () => {
        const zipCode = '123456789';
        cy.get('input[name="zipCode"]')
            .type(zipCode)
            .should('have.value', '12345-6789'); // Assuming the format is 12345-6789
    });

    it('should not accept invalid ZIP code format', () => {
        const invalidZipCode = '1234';
        cy.get('input[name="zipCode"]')
            .type(invalidZipCode)
            .should('have.value', ''); // Assuming the field clears invalid input
    });
});
